    "description": "French Avenue An Equestrian Series Olena — это популярный женский аромат от известного арабского бренда Fragrance World (выпускаемый в рамках их премиальной линейки French Avenue). Парфюм относится к группе цветочные, фруктовые, гурманские и широко известен как более доступный, но качественный аналог (дюп) селективного аромата Oriana от Parfums de Marly.\n\nПарфюмерная композиция представляет собой сочетание ярких цитрусов, сочных ягод и воздушных кондитерских нот:\nВерхние ноты: сочный коктейль из мандарина, бергамота, грейпфрута и апельсина.\nСредние ноты: нежный цветок апельсина (флёрдоранж), кисло-сладкая малина и черная смородина.\nБазовые ноты: воздушное маршмеллоу, взбитые сливки, чувственный мускус и амбретта.\n\nАромат создает нежный, игривый и очень женственный шлейф, напоминающий легкое ягодное суфле или сливочную сахарную вату с цитрусовой свежестью.",
