    "description": "Это цветочная парфюмерная вода, которую бренд выпустил в 2006 году. Создатели хотели передать атмосферу современного Лондона: например, прогулку после дождя, когда в воздухе витает аромат мокрых тротуаров, парков, жимолости и жасмина. Многие ассоциируют парфюм с «духом дождливого дня», серым лондонским небом и элегантным тренчем.\n\nВерхние ноты: жимолость, танжерин, роза.\nНоты сердца: жасмин, тиаре (белый цветок гардении таитянской, который даёт кремовые, чуть кокосовые оттенки), пион, клементин.\nБазовые ноты: мускус, сандал, пачули.\n\nВ целом композиция получается сбалансированной: свежая и цветочная в начале, с тёплой, обволакивающей базой.",
