    "description": "С 1951 дом AJMAL выпускает пышные, сияющие обилием оттенков ароматы, влюбляющие в себя миллионы людей по всему миру.\n\nAmber Zest - это соблазнительный и чарующий аромат для мужчин и женщин.\nОн открывается освежающим и в то же время пленительным аккордом бергамота, грейпфрута, лаванды, мускатного шалфея и герани.\n\nЭнергичное цитрусовое начало переходит в теплое и пряное сердце из шафрана и пачули, мягко дополненное силой кашемирового дерева.\nБазовые ноты сплетаются с манящими нотами амбры в центре, разделяя сцену с завораживающим мускусом и сладостью бобов тонка.\n\nВерхние ноты: Бергамот, грейпфрут, лаванда, мускатный шалфeй и герань. Создают яркий, свежий и слегка травянистый старт.\nСредние ноты: Шафран, пачули и кашемировое дерево. Формируют пряное, обволакивающее и бархатистое «сердце».\nБазовые ноты: Амбра, мускус и бобы тонка. Оставляют стойкий, притягательный и сладковато-смолистый шлейф",
