    "description": "Это восхитительная парфюмерная композиция, которая погружает в атмосферу тропических путешествий и оставляет за собой шлейф незабываемых воспоминаний. Этот аромат, созданный мастером парфюмерного искусства Жан-Луи Сьозаком, предназначен для женщин, которые жаждут окутать себя загадочной, но в то же время притягательной сладостью.\n\nTropical Kiss становится идеальным выбором для весенне-летнего сезона, когда его солнечное обаяние особенно уместно. Этот аромат подойдет для женщин с уверенной жизненной позицией, стремящихся к самовыражению и жаждущих придавать своему образу нотку загадки и очарования. French Avenue Tropical Kiss — это не просто парфюм, а приглашение в мир ощущений и эмоций, знакомящий с экзотическими дебютами и зрелищными путешествиями в каждый миг вашей жизни.\n\nВерхние ноты: спелое манго, ромашка, цветок апельсина (флёрдоранж).\nСредние ноты: кокос, иланг-иланг, корень ириса.\nБазовые ноты: мадагаскарская ваниль, бензоин, амбра",
