    "description": "Ambre Pimente — про благородную сложность и уют без излишней сладости. Пряный старт моментально бодрит, сердце из кедра, гваяка и амбры добавляет статусный древесно-тёплый характер, а база из мускуса и ветивера делает шлейф стойким и узнаваемым.\n\nЛучше всего аромат раскрывается в прохладное время года: осенью и зимой его пряные и древесные грани становятся глубже, а в мороз он даёт красивый, заметный шлейф. Отлично сочетается с лаконичными образами: шерстяной костюм, кашемировое пальто, кожаный аксессуар. Это выбор для тех, кто хочет звучать дорого и сдержанно — и при этом оставаться в памяти.\n\nВерхние ноты: красный апельсин, личи.\nНоты сердца: роза, жасмин, перец.\nБазовые ноты: ваниль, пачули, бензоин",
