    "description": "Ajmal Ambre Pimente — это восточно-древесный нишевый аромат-унисекс, выпущенный известным парфюмерным домом из ОАЭ Ajmal в 2012 году. Композиция сочетает в себе теплоту амбры, выраженную остроту специй и благородные древесные оттенки. Парфюм обладает отличной стойкостью и интимным, обволакивающим звучанием, которое создает эффект «второй кожи».\n\nКомпозиция не имеет классического трехступенчатого раскрытия и звучит достаточно монолитно, но в ней четко выделяются следующие аккорды:\nПряный старт: Острые специи (черный и розовый перец, кардамон) задают динамичное и согревающее начало.\nДревесное сердце: Дымный, смолистый гваяк и прохладный белый кедр уравновешивают жар пряностей.\nБазовая основа: Чувственный мускус и теплая амбра формируют мягкий, бархатистый шлейф",
    "url": "http://volodiumparfum.ru/catalog/tproduct/694060228352-ajmal-ambre-pimente"
