    "description": "Популярный цветочно-фруктовый женский аромат, выпущенный известным парфюмерным домом из ОАЭ Ajmal в 2011 году. Он позиционируется как роскошная, но доступная композиция, сочетающая восточную глубину с традициями европейского люкса.\n\nВерхние ноты: спелая малина и сочный лимон.\nСредние ноты: цветок апельсина (флердоранж), гардения, жасмин, а также легкие фруктовые и пряные оттенки.\nБазовые ноты: амбра, мускус, ваниль, древесные и мягкие пудровые аккорды.\n\nСтойкость: высокая (от 6 до 12 часов на коже и более суток на одежде).\nШлейф: яркий, заполняющий пространство, заметный на расстоянии вытянутой руки.\nСезонность: лучше всего раскрывается в прохладное время года (осень, зима), окутывая уютным «золотым» теплом",
