    "description": "Нежный, романтичный и невероятно уютный аромат, который переносит в атмосферу вечернего Парижа. Date in Paris раскрывается мягкой сладостью, воздушными цветочными аккордами и сливочно-ванильным шлейфом, создавая ощущение лёгкости, тепла и беззаботного счастья. Композиция звучит женственно, элегантно и очень притягательно, словно воспоминание об идеальном свидании в городе любви.\n\nВерхние ноты: Груша, Бергамот, Красные ягоды\nНоты сердца: Жасмин, Роза, Цветок апельсина\nБазовые ноты: Ваниль, Мускус, Сандал, Карамель\n\nСтойкость: 8–10 часов\nШлейф: Средний-высокий — мягкий, сладкий и окутывающий\nГруппа ароматов — Цветочные, Фруктовые, Гурманские\nТип продукта — Eau de Parfum\n\nИдеальный аромат для свиданий, прогулок и моментов, когда хочется подчеркнуть свою нежность и женственность.",
