    "description": "Современный нишевый бестселлер, который покорил любителей чистых древесных ароматов по всему миру. Bois Impérial сочетает свежие пряности, зелёные акценты и благородные древесные ноты, создавая ощущение дорогой чистоты и уверенности. Композиция звучит ярко, объёмно и очень современно, раскрываясь на коже благородным древесно-амбровым шлейфом. Универсальный аромат, который одинаково эффектно звучит в любое время года.\n\nВерхние ноты: Тайский базилик, Перец тимут, Грейпфрут\nНоты сердца: Ветивер, Петулия, Зелёные аккорды\nБазовые ноты: Akigalawood, Амброксан, Пачули\n\nСтойкость: Очень высокая — 10–14 часов\nШлейф: Выраженный — современный, древесный и комплиментарный\nГруппа ароматов — Древесные, Пряные, Фужерные\nТип продукта — Eau de Parfum\n\nОдин из самых популярных нишевых ароматов последних лет. Часто выбирают за сочетание свежести, статуса и впечатляющей стойкости.",
