    "description": "Величественный и насыщенный аромат, созданный для тех, кто любит яркое присутствие и дорогой шлейф. Amber Empire встречает сочным ананасом и пряным розовым перцем, создавая контраст между сладостью фруктов и благородной остротой специй. В сердце композиции раскрываются тёплые древесные аккорды кашемирового дерева и жасмин, которые делают звучание глубоким и элегантным. База из амбры, дубового мха и белого мускуса окутывает кожу густым, роскошным шлейфом, оставляя впечатление уверенности и статуса.\n\nВерхние ноты: Ананас, Розовый перец\nНоты сердца: Кашемировое дерево, Жасмин\nБазовые ноты: Амбра, Дубовый мох, Белый мускус\n\nСтойкость: Высокая — 8–12 часов\nШлейф: Выраженный — заметен на расстоянии нескольких метров\nГруппа ароматов: Древесные, Амбровые\nТип продукта: Eau de Parfum",
    "url": "http://volodiumparfum.ru/catalog/tproduct/482503118042-french-avenue-amber-empire"
