    "description": "Аромат, в котором восточная чувственность переплетается с благородной пряностью. Amber & Spices открывается свежими и слегка пряными нотами мускатного ореха и розы, создавая необычное сочетание тепла и лёгкой прохлады. Постепенно композиция становится более насыщенной: драгоценное удовое дерево и тёплая амбра придают аромату глубину и характер. Финальные аккорды сандала и специй оставляют роскошный восточный шлейф, который долго сопровождает своего владельца и подчёркивает его индивидуальность.\n\nВерхние ноты: Роза, Мускатный орех\nНоты сердца: Уд, Амбра\nБазовые ноты: Сандал, Специи\n\nСтойкость: Очень высокая — 10–14 часов\nШлейф: Насыщенный — ощущается на большом расстоянии\nГруппа ароматов: Восточные, Пряные\nТип продукта: Eau de Parfum",
