    "image": "https://static.tildacdn.com/stor6536-3636-4530-b966-336538323465/ef591f4468a370e8459ebceb2563b698.png",
    "badge": "",
    "prices": {
      "3ml": 585,
      "5ml": 925,
      "10ml": 1750,
      "15ml": 2475,
      "20ml": 3100
    },
    "description": "Аромат вдохновлён американской поп-культурой и историями о древних караванах, которые перевозили экзотические орехи кола. Создатели хотели передать контраст: бодрящую свежесть газировки и тёплую, томную основу из бобов тонка. В описаниях встречаются ассоциации с тропическим отдыхом, коктейлем «Куба Либре» (кола с ромом) и даже с атмосферой магазина.\n\nВерхние ноты: сицилийский лимон, мускатный орех, корица, чёрная вишня. Старт получается ярким: цитрусовая свежесть сочетается с пряной теплотой и сочной терпкостью вишни.\nНоты сердца: кока-кола, индонезийские пачули, цветок апельсина. Здесь раскрывается главная «фишка» — игристая, сладковатая нота колы, которую уравновешивают землистые пачули и нежный цветочный акцент.\nБазовые ноты (шлейф): бразильские бобы тонка, ваниль, бензоин, лабданум. База обволакивает: бобы тонка и ваниль дают тёплую, сладковатую основу, а бензоин и лабданум добавляют бальзамические, чуть дымные оттенки\n\nЧаще всего его рекомендуют для прохладного времени года — осени, зимы. В жару композиция может показаться слишком насыщенной. При этом аромат универсален: его можно носить и днём, и вечером, и для повседневного использования, и для особого случая.",
