    "description": "Montale Wild Pears — это фруктово‑цветочный унисекс‑аромат от французского нишевого бренда Montale, выпущен в 2011 году парфюмером Пьером Монталем. Его часто называют «ароматом-настроением»: он про сочную грушу, лёгкую пряность и уютную сладковатую базу.\n\nВерхние ноты: бергамот и груша. Старт яркий и свежий: бергамот даёт цитрусовую кислинку, а груша — ту самую узнаваемую сладость, из‑за которой многие слышат отголоски газировки «Дюшес».\nНоты сердца: ландыш и гвоздика. Ландыш добавляет нежности и «прозрачности», а гвоздика — пряную остроту: именно она делает аромат не банальным, а чуть более сложным.\nБазовые ноты: мускус, сандал, ваниль. База тёплая и обволакивающая: сандал даёт древесную мягкость, ваниль — сладкое послевкусие, а мускус закрепляет композицию и усиливает шлейф.\n\nСезон: лучше всего раскрывается весной и осенью. Летом может казаться слишком сладким, а зимой пряные и сладкие ноты звучат уютнее.\nПовод: на каждый день, прогулки, неформальные встречи. Хорошо работает как аромат для поднятия настроения.\nДля кого: унисекс, подойдёт тем, кто любит фруктовые ароматы, но хочет, чтобы они были не плоскими, а с характером.",
