    "description": "Аромат, вдохновлённый моментами, которые хочется переживать снова и снова. One More Time открывается ярким цитрусовым аккордом бергамота и лимона, наполненным бодрящей свежестью и лёгкой сладостью фруктов. В сердце композиции раскрываются сочные фруктовые ноты и нежные цветочные оттенки, создавая ощущение лёгкости и беззаботности. Постепенно аромат становится более мягким и чувственным благодаря сочетанию мускуса, древесных нот и амбры, оставляя чистый, современный и притягательный шлейф.\n\nВерхние ноты: Бергамот, Лимон, Цитрусы\nНоты сердца: Фруктовые ноты, Цветочные аккорды\nБазовые ноты: Мускус, Амбра, Древесные ноты\n\nСтойкость: Средняя — 5–7 часов\nШлейф: Средний — ощущается на расстоянии вытянутой руки\nГруппа ароматов: Фруктовые, Мускусные\nТип продукта: Eau de Parfum",
