    "description": "Marc-Antoine Barrois Ganymede — это культовый нишевый аромат-унисекс, выпущенный во Франции в 2019 году и ставший настоящим феноменом в современной парфюмерии. Композиция создана знаменитым парфюмером Квентином Бишем (Quentin Bisch) и названа в честь Ганимеда — скалистого спутника Юпитера. Аромат приобрел мировую популярность благодаря своему авангардному, футуристическому звучанию, которое часто описывают как «запах космоса», «глянцевого журнала» или «дорогого минимализма»\n\nВерхние ноты: итальянский мандарин и теплый пряный шафран.\nСредние ноты: китайский османтус (с оттенком абрикоса), бессмертник и лист фиалки.\nБазовые ноты: минеральные ноты, мягкая замша, пачули, кедр и молекула Akigalawood (придающая сухой древесно-перечный характер)",
