    "description": "RudRoss Montana — это легкий, воздушный цветочно-фруктовый аромат категории «унисекс», выпущенный британским нишевым брендом RudRoss в 2025 году. Композиция вдохновлена эстетикой горного воздуха, свежестью утренней природы и историей золотой лихорадки в американском штате Монтана. Аромат позиционируется как чистый, искрящийся и комплиментарный, идеальный для теплого времени года\n\nВерхние ноты: сочный нектарин, прохладные альдегиды и искристый лимон.\nСредние ноты: нежный ландыш, воздушная фрезия, чувственный жасмин, терпкий грейпфрут и зеленый ветивер.\nБазовые ноты: теплая амбра, сливочный сандал, сладкая ваниль и синтетический мускус Galaxolide (галаксолид)\n\nНесмотря на кажущуюся легкость и воздушность, парфюм обладает отличной стойкостью и оставляет заметный, комплиментарный шлейф. В жару он раскрывается как мягкий и женственный, а в прохладную погоду может звучать более резко и колко",
