    "description": "Загадочный, густой и гипнотический аромат, который давно стал легендой нишевой парфюмерии. Black Afgano погружает в атмосферу тёмной роскоши с первых секунд звучания. Композиция открывается насыщенными зелёными аккордами конопли и травяными оттенками, создавая необычное и интригующее начало. Постепенно аромат становится более глубоким: древесные ноты, табак и смолы формируют плотное, дымное сердце. В базе раскрываются благородный уд и кофе, оставляя тёплый, тягучий и невероятно харизматичный шлейф, который невозможно спутать ни с чем другим.\n\nВерхние ноты: Конопля, Зелёные ноты\nНоты сердца: Смолы, Древесные ноты, Табак, Кофе\nБазовые ноты: Уд, Ладан\n\nСтойкость: Очень высокая — 12+ часов\nШлейф: Насыщенный — заметен на большом расстоянии\nГруппа ароматов: Древесные, Фужерные\nТип продукта: Extrait de Parfum",
