    "description": "Источником вдохновения для названия и профиля аромата стали свойства нейромедиатора GABA (ГАМК), который помогает снижать тревожность и страх.\nПарфюмерная композиция настраивает на расслабление и спокойствие. Погрузиться в мягкое облако безмятежности помогают чарующие ноты османтуса и жасмина, окутанные приятной фруктовой свежестью мандарина и апельсина.\nУмиротворяющие объятия мускуса, акигалавуда и амброксана дарят моменты удовольствия, помогая отвлечься от забот и стресса. Расслабляющий, но в то же время яркий и чувственный аромат – парфюмерный проводник к чувству беззаботности и гармонии.\n\nВерхние ноты: Итальянский мандарин, Апельсин, Лаванда\nНоты сердца: Османтус, Жасмин самбак\nБазовые ноты: Akigalawood, Амброксан, Мускус\n\nСтойкость: Средняя — 6–8 часов\nШлейф: Умеренный — чистый, близкий к коже\nГруппа ароматов: Цитрусовые, ароматические, древесно-мускусные\nТип продукта: Parfum",
