    "description": "Яркий и необычный аромат, в котором сладкие фруктовые аккорды переплетаются с восточной теплотой. Ajayeb Dubai Portrait раскрывается сочным манго и освежающим апельсином, создавая солнечное и жизнерадостное настроение. В сердце композиции звучат нежные цветочные оттенки жасмина и сладковато-пряный сандал, придавая аромату мягкость и объём. Постепенно аромат становится более глубоким благодаря сочетанию ванили, мускуса и амбры, оставляя уютный, тёплый и притягательный шлейф с лёгким гурманским оттенком.\n\nВерхние ноты: Манго, Апельсин\nНоты сердца: Жасмин, Сандал\nБазовые ноты: Ваниль, Амбра, Мускус\n\nСтойкость: Высокая — 8–10 часов\nШлейф: Выраженный — хорошо ощущается окружающими\nГруппа ароматов: Восточные, Фруктовые\nТип продукта: Eau de Parfum",
