    "description": "Аромат, который напоминает дорогой десерт в роскошном ресторане. Тёплый бокал выдержанного коньяка, ванильная выпечка, щепотка корицы и мягкая древесная база создают ощущение абсолютного комфорта и удовольствия. Kismet Magic раскрывается насыщенным аккордом коньяка, который постепенно переплетается со сладостью бобов тонка и ванили. В шлейфе появляются сливочные оттенки пралине и благородного сандала, делая аромат густым, уютным и невероятно притягательным.\nЭто аромат для вечеров, когда хочется выглядеть дорого, уверенно и оставить после себя запоминающийся след.\n\nВерхняя нота: Коньяк\nНоты сердца: Корица, Бобы тонка, Дуб\nБазовые ноты: Ваниль, Пралине, Сандал\n\nСтойкость: Высокая — 8–12 часов\nШлейф: Выраженный — заметен окружающим\nГруппа ароматов: Восточные, Гурманские\nТип продукта: Eau de Parfum",
