    "description": "Необычный древесно-дымный аромат с ощущением концентрации, тишины и внутренней собранности. Refocus открывается холодноватыми альдегидами и ладаном, создавая эффект чистого воздуха и лёгкой минеральности. Затем композиция становится темнее: пачули, гваяковое дерево и кедр добавляют сухую древесность, а замша, лабданум, сандал и мускус делают звучание более мягким и телесным.\n\nЭто аромат про атмосферу: современный офис, тёмное дерево, ноутбук, идеальный порядок. Хорошо подойдёт для работы, встреч, вечерних выходов и любителям древесных ароматов без сладости.\n\nВерхние ноты: Альдегиды, Ладан\nНоты сердца: Пачули, Гваяковое дерево, Кедр\nБазовые ноты: Лабданум, Мускус, Замша, Сандал\n\nСтойкость: Средняя — 6–8 часов\nШлейф: Умеренный — заметен на близкой дистанции\nГруппа ароматов: Древесные, дымные, кожаные\nТип продукта: Eau de Parfum",
