    "description": "Аромат дорогой кожи, безупречного стиля и уверенности в себе. Он словно переносит в атмосферу итальянского бутика, где каждая деталь говорит о статусе и вкусе. Cuir D'Italie раскрывается мягкими пряными аккордами и бархатистыми цветочными оттенками, которые постепенно уступают место роскошной кожаной базе. В звучании чувствуется гладкая новая кожа, дорогие аксессуары и лёгкая сладость, делающая аромат не грубым, а элегантным и притягательным.\n\nСо временем композиция становится теплее и глубже: древесные ноты, мускус и амбра создают ощущение дорогого шлейфа, который остаётся на одежде и коже до самого вечера.\n\nВерхние ноты: Шафран, Специи\nНоты сердца: Кожа, Цветочные аккорды\nБазовые ноты: Амбра, Древесные ноты, Мускус\n\nСтойкость: Высокая — 8–10 часов\nШлейф: Выраженный — заметен окружающим\nГруппа ароматов: Кожаные, Восточные\nТип продукта: Eau de Parfum",
    "url": "http://volodiumparfum.ru/catalog/tproduct/590384351932-rp-paris-cuir-ditalie"
