    "description": "Аромат, который будто создан для романтических вечеров и моментов, когда хочется быть ближе. Rayhaan Kiss звучит чувственно, сладко и невероятно притягательно, создавая вокруг владельца атмосферу тепла и лёгкого соблазна. Это тот случай, когда аромат не кричит о себе, а мягко притягивает внимание и остаётся в памяти.\n\nС первых секунд композиция встречает сочными фруктовыми нотами и искрящейся сладостью, создавая ощущение праздника и беззаботности. В сердце раскрываются нежные цветочные аккорды, которые делают аромат более утончённым и воздушным. Постепенно звучание становится глубже и уютнее: сливочная ваниль, белый мускус и тёплая амбра формируют бархатистый шлейф, который хочется ощущать снова и снова.\n\nRayhaan Kiss идеально подойдёт для свиданий, вечерних прогулок и ситуаций, когда хочется подчеркнуть свою привлекательность без лишней навязчивости. Аромат создаёт ощущение ухоженности, мягкости и дорогого сладкого звучания.\n\nВерхние ноты: Красные ягоды, Мандарин, Фруктовые аккорды\nНоты сердца: Жасмин, Роза, Цветок апельсина\nБазовые ноты: Ваниль, Амбра, Белый мускус\n\nСтойкость: Высокая — 8–10 часов\nШлейф: Выраженный — оставляет нежный сладкий след\nГруппа ароматов: Цветочно-фруктовые, Восточные\nТип продукта: Eau de Parfum",
