    "description": "Аромат, который напоминает дорогой десерт из премиальной кондитерской. Нежный белый шоколад, сливочный крем и лёгкая ванильная сладость создают ощущение уюта, роскоши и абсолютного удовольствия. White Chocola звучит мягко и деликатно, но при этом обладает характером, который хочется ощущать снова и снова.\n\nКомпозиция раскрывается сладкими сливочными аккордами, постепенно переходя в тёплое ванильно-мускусное звучание. По мере раскрытия аромат становится более объёмным и бархатистым, создавая эффект дорогого гурманского облака вокруг владельца. Несмотря на сладость, аромат остаётся элегантным и не уходит в кондитерскую приторность.\n\nЭто аромат для тех, кто любит уютные комплиментарные композиции с ощущением чистоты, мягкости и дорогой сладости.\n\nВерхние ноты: Белый шоколад, Сливочные аккорды\nНоты сердца: Ваниль, Карамельные оттенки\nБазовые ноты: Мускус, Сандал, Амбра\n\nСтойкость: Высокая — 8–10 часов\nШлейф: Средне-высокий — мягко окутывает и привлекает внимание\nГруппа ароматов: Гурманские, Восточные\nТип продукта: Eau de Parfum",
