    "description": "Аромат харизмы, спокойной уверенности и дорогого мужского стиля. His Confession звучит современно и статусно: свежие пряные аккорды плавно переходят в древесно-амбровое сердце, создавая ощущение ухоженности и внутренней силы.\nПо мере раскрытия аромат становится теплее и глубже. Мускус, ваниль и древесные ноты формируют благородный шлейф, который остаётся заметным, но никогда не выглядит навязчивым.\n\nУниверсальный аромат для мужчины, который привык производить впечатление без лишних слов.\n\nВерхние ноты: Мандарин, Корица, Лаванда\nНоты сердца: Ирис, Кипарис, Бензоин, Махониал\nБазовые ноты: Ваниль, Бобы тонка, Амбра, Кедр, Пачули, Ладан\n\nСтойкость: Высокая — 8–12 часов\nШлейф: Выраженный — оставляет дорогой древесно-пряный след\nГруппа ароматов: Восточные, Древесные\nТип продукта: Eau de Parfum",
