    "description": "Минималистичный молекулярный аромат, построенный вокруг одной ноты — Cetalox. Это чистое, лёгкое и очень телесное звучание с древесно-мускусным оттенком, которое не перекрывает человека, а будто усиливает естественный запах кожи.\n\nNot a Perfume часто воспринимается по-разному: на одной коже он звучит свежо и воздушно, на другой — теплее, с амбровыми, слегка солоноватыми и древесными нюансами. Это аромат «чистой кожи после душа», белой рубашки и ощущения ухоженности. Отлично подходит на каждый день, в офис, для близкого контакта или в качестве базы для наслаивания с другими ароматами.\n\nВерхние ноты: Cetalox\nНоты сердца: Cetalox\nБазовые ноты: Cetalox\n\nСтойкость: Средняя — 5–8 часов\nШлейф: Умеренный — ощущается близко к коже\nГруппа ароматов: Древесные, мускусные, амбровые\nТип продукта: Eau de Parfum",
