    "description": "Насыщенный гурманский аромат с тёплым восточным характером. Khamrah начинается яркой корицей, мускатным орехом и бергамотом, а затем быстро становится плотнее и слаще: в сердце слышны финики, пралине и лёгкий цветочный оттенок туберозы. База раскрывается ванилью, бобами тонка, бензоином, миррой и амбровой древесиной.\n\nПо ощущению это аромат пряного десерта, фиников в карамели и горячего напитка со специями. Он густой, уютный и заметный, особенно красиво раскрывается в прохладную погоду, вечером или на выход. Не самый универсальный вариант для жары, зато отличный выбор для тех, кто любит сладкие, тёплые и комплиментарные ароматы.\n\nВерхние ноты: Корица, Мускатный орех, Бергамот\nНоты сердца: Финики, Пралине, Тубероза, Mahonial\nБазовые ноты: Ваниль, Бобы тонка, Амбровая древесина, Мирра, Бензоин, Akigalawood\n\nСтойкость: Высокая — 8–12 часов\nШлейф: Выраженный — заметен окружающим\nГруппа ароматов: Восточные, пряные, гурманские\nТип продукта: Eau de Parfum",
