    "description": "Элегантный цветочно-древесный аромат, в котором мягкие белые цветы соединяются с тёплой древесной базой. Gucci Bamboo начинается бергамотом и цветами апельсина, затем раскрывается жасмином, иланг-илангом и лилией. В финале остаётся сливочный сандал, ваниль и лёгкая тёплая древесность.\n\nНесмотря на название, аромат не про зелёный бамбук и не про свежую траву. Это скорее чистый, ухоженный и женственный парфюм с мягкой цветочной сладостью и спокойной древесной основой. Хорошо подойдёт для офиса, повседневных образов, деловых встреч и тех случаев, когда хочется звучать аккуратно, дорого и ненавязчиво.\n\nВерхние ноты: Бергамот, Цветок апельсина\nНоты сердца: Иланг-иланг, Лилия, Жасмин\nБазовые ноты: Сандал, Ваниль, Амбра\n\nСтойкость: Средняя — 6–8 часов\nШлейф: Умеренный — ощущается на близкой дистанции\nГруппа ароматов: Цветочные, древесные\nТип продукта: Eau de Parfum",
    "url": "http://volodiumparfum.ru/catalog/tproduct/337322152752-gucci-bamboo"
