    "description": "Богатый фруктово-кожаный аромат с благородным восточным характером. С первых минут раскрывается сочными ягодами и фруктами, которые быстро переходят в глубокое кожаное сердце с лёгкими дымными оттенками. В базе звучат амбра, уд и древесные аккорды, создавая тёплый, дорогой и статусный шлейф.\nАромат воспринимается как уверенный, зрелый и харизматичный — сладость здесь сбалансирована кожей и древесиной, благодаря чему композиция остаётся благородной и выразительной.\n\nВерхние ноты: Малина, Шафран\nНоты сердца: Кожа, Пачули\nБазовые ноты: Уд, Амбра, Ветивер\n\nСтойкость: 10–14 часов\nШлейф: Высокий\nОбраз: чёрный премиальный автомобиль, золотые часы и уверенность человека, который привык добиваться своего.",
