    "description": "Сочный тропический аромат с манго, кокосом и мягкой сливочной базой. Yara Tous открывается яркими фруктами: здесь чувствуется спелое манго, маракуйя и кокосовая сладость. Затем аромат становится более воздушным благодаря жасмину, гелиотропу и цветам апельсина, а в базе остаются ваниль, мускус и кашмеран.\n\nЭто настроение отпуска, солнечной кожи и фруктового коктейля у бассейна. Аромат сладкий, но не тяжёлый: в нём больше сочности и кремовой мягкости, чем густой восточной сладости. Хорошо подойдёт на весну, лето, отпуск и просто для тех дней, когда хочется добавить в образ больше лёгкости и яркости.\n\nВерхние ноты: Манго, Кокос, Маракуйя\nНоты сердца: Жасмин, Гелиотроп, Цветок апельсина\nБазовые ноты: Ваниль, Мускус, Кашмеран\n\nСтойкость: Средняя — 5–7 часов\nШлейф: Умеренный — заметен на близкой дистанции\nГруппа ароматов: Цветочные, фруктовые, гурманские\nТип продукта: Eau de Parfum",
