    "description": "Верхние ноты: персик и жасмин. Старт получается сочным и бархатистым: мягкая фруктовая сладость персика сочетается с чувственным, чуть терпким жасмином.\nНоты сердца: карамель и амбра. Здесь раскрывается гурманская, сливочная грань (карамель скорее напоминает молочный десерт, а не жжёную), а амбра добавляет тепло, смолистость и глубину.\nБазовые ноты: пачули и сандал. База формирует обволакивающий шлейф: сандал даёт кремовые, мягкие древесные оттенки, а пачули — землисто-древесные, слегка камфорные ноты, которые обеспечивают стойкость.\n\nYara Moi - тёплый, сладкий, но не приторный, чувственный и уютный аромат. В нём гармонично переплетаются фруктовые, цветочные, гурманские и древесные аккорды. Он создаёт ощущение комфорта и роскоши.\n\nЕго рекомендуют для вечерних выходов, романтических встреч, но при этом ненавязчивая сладость делает его уместным и для дневных дел — прогулки, встречи с подругами, даже офиса. Однако для жаркого лета он может быть тяжеловат, а вот в прохладную погоду (осень, зима) раскрывается лучше.",
