    "description": "Дерзкий и современный аромат с рок-н-рольным характером. Just Rock! сочетает дымные древесные аккорды, благородный ладан и сладковатую ваниль, создавая необычное и притягательное звучание. Аромат одновременно бунтарский и элегантный, идеально подчёркивающий уверенность в себе и стремление выделяться из толпы. Глубокий, тёплый и очень атмосферный, он отлично раскрывается в прохладную погоду.\n\nВерхние ноты: Ладан, Чёрный перец\nНоты сердца: Пачули, Древесные аккорды\nБазовые ноты: Ваниль, Бобы тонка\n\nСтойкость: Высокая — 8–12 часов\nШлейф: Средний-высокий — тёплый, обволакивающий и запоминающийся\nГруппа ароматов — Восточные, Древесные\nТип продукта — Eau de Parfum\n\nАромат для тех, кто ценит свободу, стиль и яркую индивидуальность. Идеально подходит для вечера, осени и прохладных дней.",
