    "description": "RudRoss Road to Paradise — это селективный нишевый аромат-унисекс, выпущенный в 2023 году, который относится к группе древесных и гурманских парфюмов. Концепция аромата строится вокруг идеи о том, что рай — это не конкретная географическая точка, а особое гармоничное состояние души, наполненное уютом и роскошью.\n\nВерхние ноты: Османтус, Белый чай\nСредние ноты: Сандал, Цветок апельсина (флёрдоранж)\nБазовые ноты: Молоко, Ваниль, Кашемировое дерево (кашмеран), Амбервуд",
