    "description": "Концепция аромата — современная, элегантная женственность: образ смелой, романтичной и уверенной в себе женщины.\n\nВерхние ноты: итальянский мандарин, нероли, томат. Старт получается свежим: цитрусовая свежесть мандарина сочетается с искристой сладостью нероли и лёгкой, чуть травянистой нотой томата.\nНоты сердца: лаванда, жасмин, георгин. В сердце раскрывается нежный цветочный букет: гипнотический жасмин, спокойная лаванда и свежий георгин.\nБазовые ноты: замша, фиалка, пачули. База обволакивает: бархатистая замша, пудровая фиалка и смолистые пачули создают тёплый, чуть анималистический шлейф.\n\nАромат -нежный, элегантный, с приятной пудровой сладостью. В нём гармонично переплетаются свежесть цветов, мягкость замши и деликатная пудровость фиалки. Звучание получается сбалансированным: не слишком лёгким, но и не тяжёлым, подходит и для повседневного использования, и для вечера.",
