    "description": "Свежий зелёно-водный аромат с ощущением морского воздуха, влажной растительности и прохладной чистоты. Seychelles Breeze начинает звучание ревенем, фиалковым листом и мокрой зеленью: здесь есть лёгкая кислинка, зелёная сочность и эффект прохладного ветра после дождя.\n\nВ сердце появляются фрезия, ирис, цветок апельсина и водяная лилия. Они делают аромат более воздушным, цветочным и слегка акватическим, но без ощущения обычного «морского» парфюма. База из амброксана, кедра, мускуса, гелиотропа и мха добавляет древесную чистоту и мягкую стойкость на коже.\n\nЭто аромат для весны, лета, отдыха, прогулок у воды и тех дней, когда хочется пахнуть свежо, зелено и необычно.\n\nВерхние ноты: Ревень, Фиалка, Зелёный аккорд, Зелёные листья\nНоты сердца: Цветок апельсина, Фрезия, Ирис, Водяная лилия\nБазовые ноты: Амброксан, Кедр, Мускус, Гелиотроп, Мох\n\nСтойкость: Высокая — 8–10 часов\nШлейф: Выраженный — хорошо ощущается окружающим\nГруппа ароматов: Зелёные, цветочные, водные\nТип продукта: Eau de Parfum",
