    "description": "Роскошный фруктово-мускусный аромат с ярким средиземноморским характером. Erba Gold открывается сочными цитрусами и спелыми фруктами, создавая ощущение солнечного отдыха на побережье. Постепенно аромат становится мягче и глубже, раскрываясь бархатистым мускусом и благородной амброй. Композиция звучит дорого, чисто и очень комплиментарно, собирая внимание окружающих.\n\nВерхние ноты: Лимон, Апельсин, Бергамот, Имбирь\nНоты сердца: Яблоко, Дыня, Груша, Специи\nБазовые ноты: Белый мускус, Амбра, Ваниль\n\nСтойкость: Очень высокая — 10–14 часов\nШлейф: Выраженный — яркий, фруктово-мускусный и долгоиграющий\nГруппа ароматов — Фруктовые, Цитрусовые, Мускусные\nТип продукта — Eau de Parfum\n\nОтлично раскрывается весной и летом, оставляя роскошный шлейф.",
