    "description": "Сочный, густой и чуть провокационный аромат вишнёвого ликёра с миндальной горчинкой. Lost Cherry открывается тёмной черешней, вишнёвым сиропом и горьким миндалём, создавая почти десертное, алкогольное звучание. Затем появляются роза и жасмин, а в базе остаются ваниль, бобы тонка, перуанский бальзам и древесные ноты.\n\nОсобенно красиво раскрывается вечером, в прохладную погоду, на свиданиях и выходах, когда хочется, чтобы аромат был частью образа.\n\nВерхние ноты: Чёрная вишня, Вишнёвый ликёр, Горький миндаль\nНоты сердца: Вишнёвый сироп, Роза, Жасмин самбак\nБазовые ноты: Бобы тонка, Ваниль, Перуанский бальзам, Сандал, Ветивер, Кедр\n\nСтойкость: Средняя — 5–8 часов\nШлейф: Умеренный — заметен на близкой дистанции\nГруппа ароматов: Восточные, фруктовые, гурманские\nТип продукта: Eau de Parfum",
