    "description": "Мягкий, уютный и очень узнаваемый аромат с ванилью, каштаном и сливочным сандалом. В начале слышны жасмин и розовый перец, затем появляется сладковатый каштановый аккорд с ванилью и взбитыми сливками. В базе остаются кашмерановое дерево и сандал — тёплые, древесные, немного молочные.\n\nThis Is Her! — про комфортную сладость без ощущения тяжёлого десерта. Он одновременно женственный, немного рок-н-ролльный и очень телесный: словно мягкий свитер, тёплая кожа и ванильный крем с древесным шлейфом. Отличный вариант на осень, зиму, прохладную весну и повседневные образы.\n\nВерхние ноты: Розовый перец, Жасмин самбак, Шёлковое дерево\nНоты сердца: Взбитые сливки, Ваниль, Каштан\nБазовые ноты: Сандал, Кашмерановое дерево\n\nСтойкость: Средняя — 6–8 часов\nШлейф: Умеренный — мягко ощущается окружающими\nГруппа ароматов: Восточные, ванильные, древесные\nТип продукта: Eau de Parfum",
