    "description": "Более насыщенная, пряная и яркая интерпретация классического Aventus. Здесь узнаваемая фруктово-цитрусовая тема раскрывается сочным ананасом, чёрной смородиной, грейпфрутом, бергамотом и лимоном. В сердце появляются имбирь, кардамон, корица, розовый перец и пачули, а база строится на ветивере, амброксане, мхе и древесных нотах.\n\nПо сравнению с классическим Aventus, Absolu ощущается более холодным, цитрусовым и пряным, с выраженной свежестью в начале и плотной древесной базой в финале. Это аромат уверенности, движения и собранности — универсальный для встреч, поездок, офиса и вечерних выходов.\n\nВерхние ноты: Ананас, Чёрная смородина, Грейпфрут, Бергамот, Лимон, Имбирь\nНоты сердца: Кардамон, Корица, Розовый перец, Пачули\nБазовые ноты: Гаитянский ветивер, Амброксан, Кашмеран, Лабданум, Мускус, Дубовый мох\n\nСтойкость: Высокая — 8–10 часов\nШлейф: Выраженный — заметен окружающим\nГруппа ароматов: Цитрусовые, древесные, шипровые\nТип продукта: Eau de Parfum",
