    "description": "Солнечный гурманский аромат с засахаренным лимоном, цветами апельсина и густой ванилью. Devotion открывается яркой цитрусовой сладостью, напоминающей лимонные цукаты и итальянскую выпечку.\n\nАромат звучит радостно, женственно и очень уютно: не как тяжёлый восточный десерт, а как тёплый лимонный крем с ванилью. Подойдёт на каждый день, свидания, весну, осень и прохладные летние вечера. Особенно понравится тем, кто любит сладкие ароматы, но хочет сохранить в них свежесть.\n\nВерхние ноты: Засахаренный лимон\nНоты сердца: Цветок апельсина\nБазовые ноты: Мадагаскарская ваниль\n\nСтойкость: Средняя — 6–8 часов\nШлейф: Умеренный — ощущается на близкой дистанции\nГруппа ароматов: Восточные, гурманские, цитрусовые\nТип продукта: Eau de Parfum",
