    "description": "Сияющий, воздушный аромат с сочной грушей, цитрусами и чистой древесно-мускусной базой. В начале особенно ярко звучат бергамот, мандарин, имбирь и спелая груша — свежо, слегка сладко и очень «искристо».\n\nBlue Talisman не уходит в обычную фруктовую сладость: он скорее про ощущение дорогой чистоты, прохладного воздуха и кожи после душа. Лёгкий по настроению, но заметный по характеру — универсальный вариант на весну, лето, офис, встречи и дни, когда хочется звучать свежо, современно и дорого.\n\nВерхние ноты: Груша, Бергамот, Имбирь, Мандарин\nНоты сердца: Цветок апельсина, Georgywood\nБазовые ноты: Ambrofix, Akigalawood, Мускус\n\nСтойкость: Средняя — 6–8 часов\nШлейф: Умеренный — заметен окружающим\nГруппа ароматов: Цитрусовые, фруктовые, древесно-мускусные\nТип продукта: Eau de Parfum",
