    "description": "Тёплый ванильный аромат с пряностями, цитрусами и благородной древесной основой. Althaïr открывается корицей, кардамоном, бергамотом и флердоранжем, поэтому ваниль здесь не звучит плоско или слишком кондитерски. Постепенно она становится более кремовой и густой, соединяясь с пралине, амброксаном, мускусом и древесными нотами.\n\nЭто аромат дорогой ванили: немного пряный, чуть дымный, с мягкой сладостью и эффектом тёплой кожи. Хорошо подойдёт на осень, зиму, вечерние встречи и для тех, кто хочет гурманский аромат без ощущения слишком липкого десерта. По характеру он универсален, но особенно красиво раскрывается на мужской коже.\n\nВерхние ноты: Корица, Кардамон, Бергамот, Цветок апельсина\nНоты сердца: Бурбонская ваниль, Элеми\nБазовые ноты: Пралине, Амброксан, Гваяковое дерево, Мускус\n\nСтойкость: Высокая — 8–10 часов\nШлейф: Выраженный — заметен окружающим\nГруппа ароматов: Восточные, ванильные, древесные\nТип продукта: Eau de Parfum",
