    "description": "Элегантный аромат в стиле классического английского костюма, вдохновлённый атмосферой ателье на Savile Row. Sartorial сочетает прохладные металлические и озоновые аккорды с лавандой, пряностями, кожей и пчелиным воском. В звучании легко представить отпаренную рубашку, дорогую шерсть, кожаные детали и старинную мастерскую портного.\n\nВ начале аромат кажется свежим и строгим: кардамон, имбирь, чёрный перец и альдегиды создают ощущение чистоты и собранности. Затем появляется мягкая лаванда, воск и кожа, а в базе остаются дубовый мох, древесина, мёд, тонка и ваниль. Sartorial звучит интеллигентно, сухо и очень статусно, без лишней сладости.\n\nВерхние ноты: Металлические ноты, Альдегиды, Кардамон, Водные ноты, Чёрный перец, Лист фиалки, Имбирь, Нероли\nНоты сердца: Лаванда, Пчелиный воск, Кожа, Липовый цвет, Цикламен\nБазовые ноты: Дубовый мох, Мёд, Древесные ноты, Пачули, Бобы тонка, Амбра, Ваниль, Белый мускус, Мирра, Кедр, Гурьюнский бальзам\n\nСтойкость: Средняя — 6–8 часов\nШлейф: Умеренный — ощущается на близкой дистанции\nГруппа ароматов: Фужерные, древесные, пряные\nТип продукта: Eau de Toilette",
