    "description": "Глубокий, тёплый и выразительный аромат с характером дорогой замши и пряной ванили. Babycat начинается искристым перцем и смолистым элеми, затем раскрывается дымным ладаном и шафраном. В базе появляется насыщенная бурбонская ваниль, сухой кедр и мягкая замша — именно они создают ощущение дорогой кожи, тёплого воздуха и вечернего города.\n\nАромат не про кондитерскую сладость: ваниль здесь темная, слегка дымная, с кожаным и древесным подтоном. Идеальный вариант для прохладной погоды, вечерних выходов и тех случаев, когда хочется оставить после себя заметное, дорогое впечатление.\n\nВерхние ноты: Розовый перец, Чёрный перец, Элеми\nНоты сердца: Ладан, Шафран\nБазовые ноты: Бурбонская ваниль, Замша, Кедр\n\nСтойкость: Высокая — 8–12 часов\nШлейф: Выраженный — заметен окружающим\nГруппа ароматов: Восточные, пряные, кожаные\nТип продукта: Eau de Parfum",
