    "description": "Мощный дымно-смолистый аромат с ладаном, пряностями, кожей и удом. Interlude Man начинается резковатой смесью бергамота, орегано и ягод пименты — старт сухой, травянистый, почти лекарственный. Затем раскрывается густое сердце из ладана, амбры, лабданума, опопонакса и ванили, а в базе остаются кожа, пачули, сандал и дымный уд.\n\nЭто аромат с очень ярким характером: тёмный, церковно-дымный, смолистый и насыщенный. Не про универсальность, а про атмосферу, статус и сильное личное присутствие. Лучше всего раскрывается в прохладе, вечером, на выходах и на тех, кто любит ладан, смолы и сложные восточные композиции.\n\nВерхние ноты: Бергамот, Орегано, Ягоды пименты\nНоты сердца: Амбра, Ладан, Лабданум, Опопонакс, Ваниль\nБазовые ноты: Уд, Кожа, Пачули, Сандал\n\nСтойкость: Очень высокая — 10–14 часов\nШлейф: Сильный — хорошо ощущается окружающими\nГруппа ароматов: Восточные, дымные, смолистые\nТип продукта: Eau de Parfum",
