    "description": "Очень уютный гурманский аромат с карамелью, ванилью, мёдом и белыми мускусами. Bianco Latte звучит так, будто рядом горячее молоко с ванилью, карамельный соус и мягкий сливочный десерт. В нём есть сладость, но она не фруктовая и не конфетная — скорее кремовая, тягучая, обволакивающая.\n\nАромат часто воспринимается как «съедобный» и очень телесный: ванильное молоко, карамель, немного мёда и чистый мускус на коже. Он особенно хорош в холодное время года, на свидания, дома, в поездках и во все моменты, когда хочется комфорта и тепла. В жару может показаться слишком густым.\n\nВерхние ноты: Карамель, Кумарин\nНоты сердца: Ваниль, Мёд\nБазовые ноты: Белый мускус, Амбра\n\nСтойкость: Высокая — 8–12 часов\nШлейф: Выраженный — мягкий, сладкий, заметный\nГруппа ароматов: Гурманские, амбровые, ванильные\nТип продукта: Eau de Parfum",
