    "description": "Свежий морской аромат с лимоном, солёным воздухом и мягкой ванильно-ветиверовой базой. Sea Breeze начинается ярким лимоном и розовым перцем, создавая ощущение прохладного бриза и цитрусовой цедры. В сердце появляются морская соль, карамбола, помело и цветок тиаре — композиция становится более солнечной, чуть фруктовой и кремово-цветочной.\n\nВ базе остаются минеральные ноты, ваниль и ветивер. Благодаря им аромат не выглядит типичным акватическим одеколоном: соль и цитрусы здесь соединяются с тёплой кожей, влажным песком и лёгкой тропической мягкостью. Бренд связывает Sea Breeze со свободой ветра и атмосферой морского побережья.\n\nВерхние ноты: Лимон, Розовый перец\nНоты сердца: Морская соль, Карамбола, Помело, Цветок тиаре\nБазовые ноты: Минеральные ноты, Ваниль, Ветивер\n\nСтойкость: Средняя — 5–7 часов\nШлейф: Умеренный — свежий, заметный на близкой дистанции\nГруппа ароматов: Фужерные, морские, цитрусовые\nТип продукта: Eau de Parfum",
