    "prices": {
      "3ml": 600,
      "5ml": 950,
      "10ml": 1800,
      "15ml": 2550,
      "20ml": 3200
    },
    "description": "Этот аромат — результат коллаборации линейки French Avenue (принадлежит эмиратскому бренду Fragrance World) и парфюмерного блогера Муниба Альвазира (Neeb).\n\nВерхние ноты: кардамон, корица, бензоин, амбра. Старт получается тёплым, пряным и обволакивающим: специи сочетаются со смолистой, чуть сладковатой подложкой из бензоина и амбры.\nНоты сердца: табак, кашемировое дерево, гелиотроп, жасмин. В сердце раскрывается более сложная текстура: сухой, благородный табак сплетается с бархатистой древесиной, а гелиотроп добавляет нежную, ванильно-миндальную пудровость с оттенком вишни и свежей выпечки. Жасмин вносит чистую цветочную сладость.\nБазовые ноты: ваниль, бобы тонка, пачули, сухая древесина. Финал получается глубоким и стойким: ваниль и бобы тонка звучат густо и тёмно, а пачули и сухая древесина добавляют землистую, успокаивающую глубину, не давая сладости уйти в приторность.\n\nRoyal Taboo - насыщенный, глубокий и очень обволакивающий аромат. В нём гармонично соединяются пряная интенсивность старта, элегантная «бархатная» середина и монументальный, стойкий финал. Композиция создаёт ощущение роскоши, таинственности и внутренней силы.",
