    "description": "Это насыщенная, «интенсивная» версия аромата Fig Tea от Патрисии де Николаи — унисекс‑парфюм из коллекции Intense. Композиция звучит как тёплый фруктовый чай в средиземноморском саду: цитрусовая свежесть в начале плавно переходит в мягкий фруктово‑цветочный аккорд, а в базе появляется травянисто‑древесная горчинка мате и мха. Аромат солнечный, но не приторный: в нём есть и сочность, и лёгкая пряность, и уютная глубина. Отлично подойдёт для тёплого времени года, когда хочется чего‑то живого, но не слишком тяжёлого.\n\nВерхние ноты: апельсин, лимон, мандарин, османтус.\nНоты сердца: давана, инжир, палисандр (розовое дерево), персик, жасмин.\nБазовые ноты: амбра, дубовый мох, гваяковое дерево, мате.",
