    "description": "Eternal Rainbow – «вечная радуга» - именно такую радугу увидел Хамуди Халил, основатель парфюмерного дома BYBOZO, прогуливаясь в окрестностях французского города Монпелье.\n\nЭтот аромат передает атмосферу цветущих французских полей после дождя. Представьте себе яркие распустившиеся цветы, покрытые каплями дождя, зеленые травы, кустарники спелых ягод, густой лес. И над всем этим разноцветным великолепием простирается яркая радуга.\n\nЭто ароматное воплощение радости и восторга! Красные цветы, спелый грейпфрут, элегантный ветивер, пикантный лавр, увенчанный сочной ежевикой — целый спектр ароматной гармонии.\n\nОсновные ноты: Ежевика, Грейпфрут, Цветочные ноты, Лавр, Ветивер\nСтойкость: Средняя — 5–7 часов\nШлейф: Умеренный — лёгкий, свежий\nГруппа ароматов: Фруктовые, цитрусовые, цветочные\nТип продукта: Eau de Parfum",
