    "description": "Яркий пряно-фруктовый аромат с малиной, мандарином и тёплой древесно-мускусной базой. В начале звучат сочная малина, розовый перец и мандарин — свежо, энергично и чуть сладко. Затем появляются фиалка, кардамон и шафран, а в финале раскрываются пачули, бобы тонка и мускус.\n\nEvoke Midnight ощущается более вечерним и насыщенным, чем обычный свежий мужской аромат. Он сочетает фруктовую сочность с сухими специями и мягкой тёплой базой, поэтому подойдёт для свиданий, мероприятий, вечерних встреч и прохладной погоды.\n\nВерхние ноты: Малина, Розовый перец, Мандарин\nНоты сердца: Фиалка, Кардамон, Шафран\nБазовые ноты: Пачули, Бобы тонка, Мускус\n\nСтойкость: Средняя — 7–9 часов\nШлейф: Умеренный — заметен окружающим\nГруппа ароматов: Пряные, фруктовые, древесно-мускусные\nТип продукта: Eau de Parfum",
