    "description": "Романтичный фруктово-цветочный аромат с ягодами, розой и тёплой смолистой базой. В начале звучат розовый перец, красные ягоды, чёрная смородина, бергамот и нероли — ярко, немного искристо и с лёгкой пряностью. Затем аромат раскрывается турецкой розой, геранью и кардамоном, а в базе становится более мягким благодаря ванили, сандалу, мускусу, кедру, амбре и ладану.\n\nLove Me — не просто сладкая ягодная роза, а более тёплый, чуть восточный цветочный аромат. В нём есть ощущение букета роз на фоне ягодного джема, сухой древесины и деликатного ладана. Лучше всего подойдёт на свидания, прохладную весну, осень и вечерние образы.\n\nВерхние ноты: Розовый перец, Красные ягоды, Чёрная смородина, Бергамот, Нероли\nНоты сердца: Турецкая роза, Герань, Кардамон\nБазовые ноты: Ладан, Амбра, Ваниль, Сандал, Мускус, Кедр\n\nСтойкость: Средняя — 6–8 часов\nШлейф: Умеренный — цветочный, мягко заметный\nГруппа ароматов: Цветочные, фруктовые, древесно-амбровые\nТип продукта: Eau de Parfum",
