    "description": "French Avenue Grow — это глубокий, восточно-древесный унисекс-аромат с выразительными сладкими, пряными и сливочными аккордами. Созданный в сотрудничестве с парфюмером Жан-Кристофом Эро, он выделяется сложной, многослойной композицией для любого сезона.\n\nВерхние ноты: Финики, давана, шафран, перец тимур (тимут) и груша.\nНоты сердца: Заварной крем, роза, жасмин, герань, пион, ландыш и финики.\nБазовые ноты: Ваниль, бобы тонка, нагармота, лабданум, бессмертник, атласский кедр, мускус и сухая древесина.\n\nПарфюм раскрывается свежей фруктовой сладостью согретой финиками груши, приправленной экзотическими пряностями. Сердце аромата смягчается благодаря сливочному заварному крему и цветочному букету, плавно переходя в плотный, шлейфовый древесно-бальзамический шлейф с роскошными акцентами ванили.",
