    "description": "Сочный фруктово-восточный аромат с кровавым апельсином, красным яблоком, персиком и тёплой ванильно-древесной базой. Forbidden Fruit начинается ярким цитрусовым аккордом с кардамоном: свежесть здесь быстро становится более сладкой и объёмной за счёт яблока, персика, розы и коктейльной ноты маргариты.\n\nВ базе раскрываются ванильная абсолютная нота, бензоин, амбра, сандал, кедр и мускус. Аромат воспринимается как фруктовый коктейль с тёплой карамельно-древесной глубиной — яркий, сладкий, но не слишком детский. Хорошо подойдёт на вечер, свидания, прохладную погоду и тем, кто любит заметные фруктовые ароматы с восточным характером.\n\nВерхние ноты: Бергамот, Кровавый апельсин, Кардамон\nНоты сердца: Красное яблоко, Персик, Маргарита, Роза\nБазовые ноты: Ванильная абсолютная нота, Бензоин, Амбра, Сандал, Кедр, Мускус\n\nСтойкость: Высокая — 8–10 часов\nШлейф: Выраженный — заметен окружающим\nГруппа ароматов: Фруктовые, восточные, гурманские\nТип продукта: Eau de Parfum",
