    "description": "Patchouli On Fire – эффектный древесно-пряный парфюм от арабского бренда AFNAN, очаровавший красивым классическим звучанием и элегантным послевкусием ценителей элитных, истинно гурманских ароматов в 2022 году. Чувственная парфюмерная композиция, практически молниеносно перешедшая в разряд классики, продолжает покорять сердца представителей сильного пола и влюблять в себя представительниц прекрасной половины человечества по всему миру и сегодня.\n\nНоты аромата: пряности, древесные ноты, пачули, лаванда, цитрус, пачули, экзотические специи",
