    "description": "Глубокий восточный экстракт с пряностями, финиками, карамелью и насыщенным удом. Oud Cadenza начинается шафраном, корицей, кардамоном, имбирём и розовым перцем — звучание горячее, пряное и немного дымное. В сердце появляются финики, карамель, ладан, мирра и уд, а база становится более густой за счёт ванили, какао, кожи, бензоина, пачули и лабданума.\n\nЭто не строгий аптечный уд, а более гурманская и роскошная его интерпретация: финики в карамели, пряности, тёмная кожа, какао и смолистая древесина. Аромат очень плотный, вечерний и статусный, лучше всего раскрывается в холодное время года, на выходах и в ситуациях, когда хочется действительно заметного звучания.\n\nВерхние ноты: Шафран, Корица, Кардамон, Мускатный орех, Имбирь, Розовый перец\nНоты сердца: Финики, Уд, Карамель, Сахарный тростник, Ладан, Амбровая древесина, Мирра, Давана\nБазовые ноты: Мадагаскарская ваниль, Масло какао, Бобы тонка, Кожа, Бензоин, Мускус, Пачули, Лабданум, Мате\n\nСтойкость: Очень высокая — 10–14 часов\nШлейф: Сильный — заметен окружающим\nГруппа ароматов: Восточные, древесные, гурманские\nТип продукта: Extrait de Parfum",
