    "uid": 170639811263,
    "brand": "SIU",
    "name": "Flawsome",
    "fullTitle": "SIU Flawsome",
    "gender": "unisex",
    "category": "perfume",
    "notesFamily": "woody",
    "image": "https://static.tildacdn.com/stor6561-6662-4036-a366-633236386234/2e56b69fc6b213c3b2b4773a1ca4d1da.png",
