    "description": "Мягкий, солнечный и очень женственный аромат с миндалём, мимозой и кокосом. В начале миндаль даёт лёгкую ореховую горчинку, а затем быстро появляется пушистая цветочная сладость мимозы, жасмина и лиатриса. Кокос делает композицию более кремовой и воздушной, словно тёплая пудра на коже.\n\nВ базе остаются ваниль, мускус и амбра. Elan звучит как мягкое золотистое облако: цветочное, слегка медовое, пудровое и уютное. Это не тяжёлый гурманский аромат, а деликатная ванильно-цветочная композиция для спокойных дней, свиданий, весны и ранней осени.\n\nВерхние ноты: Миндаль\nНоты сердца: Мимоза, Жасмин, Лиатрис, Кокос\nБазовые ноты: Ваниль, Мускус, Амбра\n\nСтойкость: Средняя — 6–8 часов\nШлейф: Умеренный — мягкий, пудровый\nГруппа ароматов: Цветочные, ванильные, пудровые\nТип продукта: Eau de Parfum",
