    "description": "Amber подойдёт тем, кто любит спокойные, обволакивающие амбры без тяжёлой восточной громкости. Тёплый, мягкий и немного медитативный амбровый аромат, в котором цветы не спорят с базой, а делают её более воздушной. Стартует бергамотом, жасмином и иланг-илангом: звучание не цитрусовое, а скорее золотисто-цветочное, с лёгкой кремовой сладостью.\n\nДальше на первый план выходит лабданум и кристаллическая амбра — смолистая, суховатая, без липкости. В финале остаются опопонакс, гелиотроп и амбровое дерево, добавляя пудровость, бальзамическую глубину и мягкое древесное тепло.\n\nВерхние ноты: Бергамот, Жасмин, Иланг-иланг\nНоты сердца: Кристаллическая амбра, Лабданум, Жасмин\nБазовые ноты: Опопонакс, Гелиотроп, Амбровое дерево\n\nСтойкость: Выше средней\nШлейф: Умеренный, тёплый и смолистый\nГруппа ароматов: Амбровые, восточные, цветочные\nТип продукта: Eau de Parfum",
