    "description": "Пудрово-цветочный аромат с лёгкой ретро-интонацией. В начале гардения, бергамот и роза дают чистое белоцветочное звучание, но довольно быстро композиция становится теплее и глубже за счёт жасмина, пиона и пряной гвоздики.\n\nВ базе пачули, бобы тонка и дуб создают мягкий кремово-древесный фон. Cotton Flower — это не аромат стирального порошка, а скорее образ свежей ткани, цветочного крема и тонкой пудры. Хороший вариант на каждый день, для офиса, спокойных прогулок и тех, кто любит чистые цветочные композиции с характером.\n\nВерхние ноты: Гардения, Бергамот, Роза\nНоты сердца: Гвоздика, Жасмин, Пион\nБазовые ноты: Пачули, Бобы тонка, Дуб\n\nСтойкость: Средняя\nШлейф: Мягкий, пудрово-цветочный\nГруппа ароматов: Цветочные, древесно-мускусные, пудровые\nТип продукта: Eau de Parfum",
