    "description": "Глубокий восточно-древесный аромат с удом, пачули и тёплой амброй. Sultan The Founder начинается густым ориентальным аккордом с дымным удом и влажной землистостью пачули. В сердце появляется кашемировое дерево, дубовый мох и амбретта — они делают композицию более мягкой, бархатистой и немного мускусной.\n\nВ базе остаются сухая амбра, лабданум и животный нюанс циветты. Аромат ощущается тёмным, статусным и собранным: не про сладость, а про плотную древесину, дым, смолы и ощущение дорогой ткани. Хорошо подойдёт на вечер, прохладную погоду и тем, кто любит выразительные удовые композиции без фруктовых или гурманских акцентов.\n\nВерхние ноты: Уд, Ориентальный аккорд, Пачули\nНоты сердца: Амбретта, Кашемировое дерево, Дубовый мох\nБазовые ноты: Сухая амбра, Лабданум, Циветта\n\nСтойкость: Высокая — 8–12 часов\nШлейф: Выраженный — заметен окружающим\nГруппа ароматов: Восточные, древесные, удовые\nТип продукта: Eau de Parfum",
