    "description": "Тёплый сливочно-гурманский аромат со сливой, ромом, кокосом и ванилью. В начале особенно заметен дуэт спелой сливы и рома: сладкий, немного алкогольный, с ощущением фруктового ликёра. Затем появляются тубероза и кокос, которые добавляют аромату кремовую белоцветочную мягкость.\n\nВ базе раскрываются пралине, мускус и ваниль. Petra звучит как сливовый десерт с ромом, кокосовым кремом и тёплой ванильной основой. Особенно красиво раскрывается в прохладную погоду, вечером, на свиданиях и в ситуациях, когда хочется сладкого, заметного и уютного аромата.\n\nВерхние ноты: Слива, Ром\nНоты сердца: Тубероза, Кокос\nБазовые ноты: Пралине, Мускус, Ваниль\n\nСтойкость: Высокая — 8–10 часов\nШлейф: Выраженный — сладкий, заметный окружающим\nГруппа ароматов: Цветочные, фруктовые, гурманские\nТип продукта: Eau de Parfum",
