    "description": "Это роскошный унисекс-аромат, который относится к группе цветочных и гурманских. Он представляет собой насыщенный сладкий десерт с пьянящими и древесными акцентами.\n\nВерхние ноты: Мадагаскарская ваниль, бурбонская ваниль и ванильная икра.\nНоты сердца: Шоколадный трюфель, ваниль, ром, пачули и жасмин.\nБазовые ноты: Абсолют ванили, карамель, бобы тонка и уд.\n\nАромат выделяется деликатным звучанием без резких нот: обволакивающая сладость ванили, карамели и шоколадного трюфеля эффектно контрастирует с глубоким аккордом рома и томным шлейфом. Это стойкий и заметный парфюм, который идеально подходит для вечернего времени и холодного сезона.",
