    "description": "Современная ваниль с орехово-сливочным стартом и лёгким эффектом подгоревшего крем-брюле. Vanilla Haze открывается миндалём, фундуком, кокосовым молоком и мандарином, поэтому сладость здесь сразу звучит объёмно: не просто ваниль, а десертная, кремовая композиция с чуть свежим цитрусовым акцентом.\n\nВ сердце появляются ванильный стручок, бобы тонка и жасмин. В базе остаются карамель, кашмеран, амбра и мускус, создавая мягкий, тёплый, немного древесный шлейф. По характеру это аромат уютный, но не инфантильный: ваниль здесь плотная, модная и чуть дымная.\n\nХорошо подойдёт на осень, зиму, свидания, вечерние выходы и всем, кто любит гурманские ароматы без ощущения дешёвой сахарной сладости.\n\nВерхние ноты: Миндаль, Фундук, Кокосовое молоко, Мандарин\nНоты сердца: Ванильный стручок, Бобы тонка, Жасмин\nБазовые ноты: Карамель, Кашмеран, Амбра, Мускус\n\nСтойкость: Высокая — 8–10 часов\nШлейф: Выраженный — заметен окружающим\nГруппа ароматов: Восточные, ванильные, древесно-гурманские\nТип продукта: Eau de Parfum",
