    "description": "Свежий, зелёный и очень чистый аромат с мятой, лаймом и прохладной тоник-цитрусовой искрой. В начале особенно ярко звучат мята, лимон и лайм — бодро, чуть терпко, с эффектом холодного напитка. Затем появляются чёрная смородина, жасмин и розмарин, добавляя композиции зелёную сочность и лёгкую ароматическую горчинку.\n\nВ базе остаются сандал, мускус, амбра и дубовый мох. Platine Blanc ощущается как светлая рубашка, мятный тоник и свежий воздух в жаркий день. Это универсальный вариант на весну, лето, офис, поездки и для тех, кто любит цитрусовые ароматы с чистым древесно-мускусным шлейфом.\n\nВерхние ноты: Мята, Лайм, Лимон, Тоник\nНоты сердца: Чёрная смородина, Жасмин, Розмарин\nБазовые ноты: Сандал, Мускус, Амбра, Дубовый мох\n\nСтойкость: Средняя — 6–8 часов\nШлейф: Умеренный — свежий, заметный на близкой дистанции\nГруппа ароматов: Цитрусовые, зелёные, ароматические\nТип продукта: Extrait de Parfum",
