    "description": "Яркий, бодрящий цитрусовый аромат с лаймом, мятой и зелёной свежестью. В начале особенно заметны апельсин, зелёный лайм и мята — звучание искристое, чуть терпкое и очень сочное. Затем композиция становится мягче за счёт жасмина, флердоранжа, герани и ириса, но сохраняет свой прохладный цитрусовый характер.\n\nВ базе появляются пачули, амбра и мускус: они добавляют аромату чистую древесно-мускусную глубину и помогают свежести держаться на коже дольше. Несмотря на название, это не солёный «икорный» аромат, а скорее очень свежий лаймово-цитрусовый коктейль с зелёными и травянистыми оттенками.\n\nОтлично подойдёт на весну, лето, отпуск, офис, жаркую погоду и для тех, кто любит чистые цитрусовые композиции с характером.\n\nВерхние ноты: Апельсин, Зелёный лайм, Мята\nНоты сердца: Жасмин, Цветок апельсина, Герань, Ирис\nБазовые ноты: Пачули, Амбра, Мускус\n\nСтойкость: Средняя — 5–7 часов\nШлейф: Умеренный — свежий, заметный на близкой дистанции\nГруппа ароматов: Цитрусовые, зелёные, ароматические\nТип продукта: Eau de Parfum",
    "url": "http://volodiumparfum.ru/catalog/tproduct/637643068543-laurent-mazzone-parfums-citron-caviar"
