    "description": "French Avenue Ripple — это древесно-фужерный унисекс-парфюм 2025 года от известного бренда. Аромат раскрывается бодрящими нотами лаванды и цитрусов, переходящими в насыщенный морской бриз с мягкими древесными аккордами, и оставляет глубокий шлейф из амбры и ладана.\n\nВерхние ноты: Бергамот, лаванда, шалфей.\nНоты сердца: Морские ноты, морская вода, кедр, сандаловое дерево.\nБазовые ноты: Амбра, ладан, мускус.\n\nЭто яркий, многогранный парфюм, который сочетает в себе свежесть и аристократичную глубину. Он отлично подойдет как для повседневного использования, так и для вечерних выходов, гармонично дополняя образ целеустремленных людей, ценящих стиль.",
