    "description": "Свежий, солнечный цитрусово-древесный аромат с очень чистым и собранным характером. Pisa открывается сочным мандарином, лимоном и бергамотом: звучание яркое, искристое, с лёгкой сладостью цедры. В сердце появляется сухой кедр, а в базе — кремовый сандал и тёплая амбра.\n\nПо настроению это аромат итальянского лета: прохладный цитрусовый напиток, светлая рубашка и нагретое солнцем дерево. Он не уходит в резкую кислотность и постепенно становится мягче, теплее и немного пудровее. Подойдёт на весну, лето, офис, поездки и как универсальный свежий аромат на каждый день.\n\nВерхние ноты: Мандарин, Лимон, Бергамот\nНоты сердца: Кедр\nБазовые ноты: Сандал, Амбра\n\nСтойкость: Средняя — 5–7 часов\nШлейф: Умеренный — свежий, заметный на близкой дистанции\nГруппа ароматов: Цитрусовые, древесные, амбровые\nТип продукта: Eau de Parfum",
