    "description": "Современный ванильный аромат, в котором сладость соединяется с прохладной лавандой и лёгкой древесной сухостью. Burberry Goddess строится вокруг трёх оттенков ванили: более воздушной и древесной ванильной инфузии, насыщенной ванильной икры и глубокой ванильной абсолюты.\n\nЛаванда добавляет аромату чистоту и делает его менее десертным: он ощущается не как пирожное, а как мягкая ваниль на коже с травянистым, чуть ароматическим акцентом. В старте также можно уловить какао и имбирь, которые добавляют лёгкую пряность. Хороший вариант на каждый день, свидания, прохладную весну и осень — для тех, кто любит ваниль, но не хочет слишком приторный гурманский аромат.\n\nВерхние ноты: Ваниль, Лаванда, Какао, Имбирь\nНоты сердца: Ванильная икра\nБазовые ноты: Ванильная абсолютa\n\nСтойкость: Средняя — 6–8 часов\nШлейф: Умеренный — мягко ощущается окружающими\nГруппа ароматов: Ароматические, ванильные, гурманские\nТип продукта: Eau de Parfum",
