    "description": "Свежая и более лёгкая интерпретация Angels’ Share, вдохновлённая охлаждённым коньячным коктейлем. В начале появляется прохладный аккорд льда и горького апельсина, который делает аромат заметно более цитрусовым и прозрачным, чем оригинал. Затем выходит коньяк с корицей — тёплый, пряный, но без густой десертной сладости.\n\nВ базе остаются бобы тонка и дубовая древесина. За счёт этого Angels’ Share On The Rocks сохраняет фирменное алкогольное звучание Kilian, но ощущается более свежим, воздушным и универсальным. Хороший вариант для весны, осени, вечерних выходов и для тех, кому нравится оригинальный Angels’ Share, но хочется меньше пралине и ванили.\n\nВерхние ноты: Аккорд льда, Горький апельсин\nНоты сердца: Коньяк, Корица\nБазовые ноты: Бобы тонка, Дуб\n\nСтойкость: Средняя — 6–8 часов\nШлейф: Умеренный — заметен на близкой дистанции\nГруппа ароматов: Древесные, пряные, алкогольные\nТип продукта: Eau de Parfum",
