    "description": "Яркий контрастный аромат, в котором терпкая маракуйя сталкивается с густым кожаным удом. Начало звучит очень сочно: экзотическая маракуйя, фруктовые ноты, шафран и турецкая роза создают эффект тропического фрукта с пряной кислинкой. Но уже через несколько минут композиция становится темнее — появляется насыщенный уд, пачули, бензоин и дымная древесина.\n\nВ базе остаются кожа, лабданум, амбра, ваниль и Akigalawood. За счёт этого Oud Maracujá не воспринимается как лёгкий фруктовый аромат: это плотная, дорогая и очень необычная композиция, где маракуйя звучит поверх тёмной кожи, смол и древесины. Идеален для вечеров, холодной погоды и тех, кто любит нишевые ароматы с сильным характером.\n\nВерхние ноты: Маракуйя, Фруктовые ноты, Шафран, Турецкая роза\nНоты сердца: Уд, Пачули, Бензоин\nБазовые ноты: Кожа, Лабданум, Амбра, Ваниль, Akigalawood\n\nСтойкость: Очень высокая — 10–14 часов\nШлейф: Сильный — заметен окружающим\nГруппа ароматов: Древесные, кожаные, фруктовые\nТип продукта: Extrait de Parfum",
