    "description": "Мягкий, бархатистый и очень уютный аромат с пудровым ирисом, маком и тёплой тонкой. Scarlet Poppy вдохновлён алыми маками на просторах Азии и построен не на зелёном цветочном звучании, а на кремовой, почти кашемировой текстуре. В начале слышны амбретта и инжир, затем появляется пудровый ирис и цветочный аккорд мака.\n\nБобы тонка в базе добавляют сладость с оттенками миндаля, ванили и табака. Аромат воспринимается как мягкий тёплый плед, дорогой крем для тела и пудровый цветочный шлейф. Хорошо подойдёт на осень, зиму, свидания и для тех, кто любит неяркую, но очень чувственную сладость.\n\nВерхние ноты: Амбретта, Инжир\nНоты сердца: Мак, Ирис, Гелиотроп\nБазовые ноты: Бобы тонка, Кедр, Мускус\n\nСтойкость: Средняя — 6–8 часов\nШлейф: Умеренный — мягкий и обволакивающий\nГруппа ароматов: Цветочные, пудровые, ванильные\nТип продукта: Cologne Intense",
