    "description": "Тёмный, пряный и очень атмосферный аромат с яблочным кальянным аккордом, табаком и густой бурбонской ванилью. В начале Smoking Hot даёт эффект горячего яблочного дыма с корицей — сладковато, пряно и немного провокационно. Затем появляется табак, дубовый мох и смолистые оттенки, а в финале остаются ваниль, пачули и мягкая древесная база.\n\nЭто аромат не про свежий табак, а про вечерний лаунж, тёплый дым, карамелизированное яблоко и дорогой алкогольный вайб. Хорошо раскрывается в холодное время года, на свиданиях, вечеринках и вечерних выходах. Особенно понравится тем, кто любит сладкие табачные ароматы, но хочет более современное и необычное звучание.\n\nВерхние ноты: Яблочный кальянный аккорд, Корица\nНоты сердца: Табак, Дубовый мох, Бессмертник\nБазовые ноты: Бурбонская ваниль, Пачули, Лакрица, Orcanox, Iso E Super, Шалфей\n\nСтойкость: Высокая — 8–10 часов\nШлейф: Выраженный — заметен окружающим\nГруппа ароматов: Восточные, табачные, пряные\nТип продукта: Eau de Parfum",
