    "description": "Stéphane Humbert Lucas 777 God of Fire — это яркий и экзотический восточно-древесный унисекс-аромат, вдохновленный ацтекским богом огня. Взрывной, сочный манго и пикантный имбирь балансируют с глубокой базой из уда и амбры, образуя шлейфовый и невероятно стойкий парфюм.\n\nВерхние ноты: Манго, имбирь, лимон и красные ягоды.\nНоты сердца: Кумарин, древесина кедра и жасмин.\nБазовые ноты: Уд, амбра, нагармота и мускус.\n\nЭтот аромат выделяется своим контрастом: тропическая фруктовая свежесть на старте плавно перетекает в теплое, дымное и чувственное раскрытие, что делает его идеальным выбором как для мужчин, так и для женщин",
