    "description": "Более яркая и современная версия La Nuit de L’Homme с фруктовой свежестью, лавандой и ванильно-древесной базой. В начале слышны зелёное яблоко, лимон и мандарин — аромат сразу кажется сочным, энергичным и более дневным, чем классическая La Nuit. Затем появляются лаванда, герань, шалфей и флердоранж.\n\nВ базе остаются ваниль, бобы тонка, кашмерановое дерево, кедр, пачули и ветивер. За счёт этого Eau Électrique сохраняет фирменную чувственность линейки, но звучит менее тёмно и более молодо: свежий, слегка сладковатый фужер с мягкой ванильной основой.\n\nХорошо подойдёт на весну, осень, свидания, вечерние прогулки и как универсальный аромат для тех, кому нравится La Nuit de L’Homme, но хочется больше яркости и свежести.\n\nВерхние ноты: Зелёное яблоко, Лимон, Мандарин\nНоты сердца: Лаванда, Герань, Шалфей, Цветок апельсина\nБазовые ноты: Ваниль, Бобы тонка, Кашмерановое дерево, Кедр, Пачули, Ветивер\n\nСтойкость: Средняя — 6–8 часов\nШлейф: Умеренный — заметен на близкой дистанции\nГруппа ароматов: Восточные, фужерные, древесные\nТип продукта: Eau de Toilette",
