    "description": "Lattafa Atheeri — нежный, воздушный аромат, в котором свежесть раннего утра сочетается с тёплой цветочной элегантностью. Он звучит деликатно, но запоминается: будто лёгкий цветочный туман с уютным ванильно‑древесным шлейфом.\n\nВерхние ноты: страстоцвет, водные аккорды («капли росы»).\nСредние ноты: орхидея, жасмин.\nБазовые ноты: ваниль, амбервуд.\n\nДля каких случаев: хорош для офиса и дневных встреч — не душит, но создаёт образ ухоженности; отлично раскрывается весной и летом; подойдёт для свиданий и прогулок, когда хочется романтичного, но ненавязчивого аромата; уместен на выставках, в кафе, на дневных мероприятиях\n\nДюп — это доступный аналог популярного парфюма: он передаёт характер и основные ноты оригинала, но стоит дешевле и выпускается под другим названием. Это не подделка, а легальная интерпретация — чтобы попробовать трендовый аромат без больших трат или носить его каждый день, не расходуя дорогой оригинал",
