    "description": "Ahmed Al Maghribi Kaaf — восточный унисекс‑аромат с пряно‑древесным характером и тёплой сладостью. Звучит статусно и обволакивающе — в духе классических ориентальных композиций.\n\nВерхние ноты: шафран, кардамон, специи — дают яркий пряный старт.\nСредние ноты: уд, роза, цветочные аккорды — создают насыщенное сердце с благородной цветочно‑смолистой глубиной.\nБазовые ноты: амбра, мускус, древесные ноты, пачули — формируют густой, стойкий шлейф.\n\nДля каких случаев: идеален для вечера, торжественных выходов и холодной погоды; уместен на семейных праздниках, ужинах, в местах, где хочется звучать «дорого» и выразительно. Из‑за насыщенности не лучший вариант для офиса или жаркого лета — лучше раскрывается в прохладное время года.\n\nДюп — это доступный аналог популярного парфюма: он передаёт характер и основные ноты оригинала, но стоит дешевле и выпускается под другим названием. Это не подделка, а легальная интерпретация — чтобы попробовать трендовый аромат без больших трат или носить его каждый день, не расходуя дорогой оригинал",
