    "description": "Это унисекс-композиция 2022 года. Старт получается бодрящим — цитрусы, прохлада мяты и лёгкая пряность перца. В сердце к свежести присоединяются землистые оттенки ветивера, пряность имбиря и нежность жасмина. А в долгом шлейфе древесные аккорды (сандал, кедр) сплетаются с дымным ладаном и многогранными пачулями.\n\nВерхние ноты: грейпфрут, лимон, мята, розовый перец.\nСредние ноты: имбирь, ветивер, жасмин.\nБазовые ноты: олибанум (ладан), сандал, кедр, пачули\n\nДля каких случаев подойдёт?\nБлагодаря свежему старту аромат хорошо работает в тёплую погоду (весна, лето), но и в прохладные сезоны раскрывается интересно за счёт тёплой, обволакивающей базы. Его можно носить и днём, и вечером — он достаточно универсален для разных выходов.\n\nДюп на Сhanel blue de Chanel\n\nДюп — это доступный аналог популярного парфюма: он передаёт характер и основные ноты оригинала, но стоит дешевле и выпускается под другим названием. Это не подделка, а легальная интерпретация — чтобы попробовать трендовый аромат без больших трат или носить его каждый день, не расходуя дорогой оригинал",
