    "notesFamily": "fresh",
    "image": "https://static.tildacdn.com/stor6365-3234-4966-b536-313234663066/ccaaad7f3b14c6f464859e98b978a2f3.webp",
    "badge": "",
    "prices": {
      "3ml": 600,
      "5ml": 950,
      "10ml": 1800,
      "15ml": 2550,
      "20ml": 3200
    },
    "description": "Глубокое, многослойное путешествие, где пряности, дым и тёплые смолы сплетаются в очень статусную и загадочную историю.\n\nВерхние ноты: ладан, кардамон, базилик, бергамот.\nСредние ноты: табак, пажитник (фенугрек), лаванда.\nБазовые ноты: уд, перуанский бальзам, бобы тонка, амбра.\n\nOpus Magnum — это аромат-заявление. Он не стремится быть лёгким и повседневным: его характер торжественный, статусный, он окутывает обладателя аурой мудрости и внутренней силы.\n\nСтойкость: хорошая — около 8 часов на коже, на одежде держится дольше.\nШлейф: заметный в первые часы, затем аромат становится ближе к коже.\nКогда лучше раскрывается: идеально для холодного времени года (осень, зима), для вечерних выходов, романтических встреч или деловых событий высокого уровня.\nСовет: из-за насыщенности достаточно 1–2 нажатий — парфюм активно заполняет пространство.\n\nДюп — это доступный аналог популярного парфюма: он передаёт характер и основные ноты оригинала, но стоит дешевле и выпускается под другим названием. Это не подделка, а легальная интерпретация — чтобы попробовать трендовый аромат без больших трат или носить его каждый день, не расходуя дорогой оригинал",
    "url": "http://volodiumparfum.ru/catalog/tproduct/108899118713-french-avenue-opus-magnum"
