    "fullTitle": "French Avenue Platine Blanc Aromatix X",
    "gender": "unisex",
    "category": "perfume",
    "notesFamily": "woody",
    "image": "https://static.tildacdn.com/stor3937-6238-4566-a464-336132653635/8beb13b87f91b6e6fec312868b6b86ad.png",
