    "prices": {
      "3ml": 600,
      "5ml": 950,
      "10ml": 1800,
      "15ml": 2550,
      "20ml": 3200
    },
    "description": "Энергичный, но при этом очень элегантный — он отлично подойдёт тем, кто любит чистые, бодрящие композиции с интересной трансформацией. Парфюмер — Muneeb Alwazeer. Аромат унисекс\n\nВерхние ноты: мята, лайм, лимон, тоник.\nСредние ноты: чёрная смородина, жасмин, розмарин.\nБазовые ноты: мускус, серая амбра, сандал, дубовый мох.\n\nPlatine Blanc Aromatix X — это история про контраст и баланс. Он начинается как искрящийся цитрусово-мятный коктейль, затем раскрывается травянисто-цветочным сердцем, а завершается тёплой, но при этом прохладной древесно-мускусной базой. Он звучит дорого и объёмно, транслируя ощущение безупречной ухоженности и внутреннего драйва, но без перехода в банальный спортивный стиль.\n\nЭто отличный выбор для любителей свежих, чистых и в то же время многогранных композиций. Аромат хорошо подойдёт для весенне-летнего сезона, повседневной носки, офиса, прогулок и путешествий. Он дарит ощущение энергии и свежести в течение всего дня.\n\nСтойкость у аромата хорошая для свежего типа — около 4–6 часов.\n\nДюп на Xerjoff Torino 21\n\nДюп — это доступный аналог популярного парфюма: он передаёт характер и основные ноты оригинала, но стоит дешевле и выпускается под другим названием. Это не подделка, а легальная интерпретация — чтобы попробовать трендовый аромат без больших трат или носить его каждый день, не расходуя дорогой оригинал",
