    "description": "Vulcan Sable создаёт ощущение «раскалённого песка и благородного огня», оставляет за собой шлейф силы, загадочности и восточной роскоши. Подходит тем, кто ценит смелые, но изысканные композиции. Его можно носить и днём, и на вечерние встречи или свидания.\n\nВерхние ноты: виски, апельсин, мандарин, кориандр.\nНоты сердца: кашмеран, бобы тонка, стиракс, анис.\nБазовые ноты: ваниль, пачули, бензоин. Шлейф получается тёплым и обволакивающим. Ваниль звучит мягко, сливочно (но не приторно).\n\nСтойкость хорошая: на коже аромат держится 6–8 часов, а на одежде может сохраняться до суток.\nАромат лучше всего раскрывается в прохладную погоду — осенью, зимой, ранней весной. В прохладные летние вечера его тоже можно носить, но основное направление всё же сезонное.\n\nИногда в раскрытии проявляются индивидуальные нюансы: кому-то слышится какао, кому-то — лёгкие дымные или даже «кожаные» оттенки. Это нормально — раскрытие очень индивидуально.\n\nДюп на Sand Dance от Stéphane Humbert Lucas 777\n\nДюп — это доступный аналог популярного парфюма: он передаёт характер и основные ноты оригинала, но стоит дешевле и выпускается под другим названием. Это не подделка, а легальная интерпретация — чтобы попробовать трендовый аромат без больших трат или носить его каждый день, не расходуя дорогой оригинал",
