    "description": "Сбалансированный, современный фужер с интересным контрастом: свежая, почти бодрящая старт сочетается с тёплой, древесно-амбровой базой. Аромат вышел в 2025 году, его создал парфюмер Жан-Луи Сьёзак (он же работал над Kouros, Fahrenheit и Opium). Часто его относят к мужским, но по характеру он вполне универсален\n\nВерхние ноты: бергамот и элеми.\nНоты сердца: лаванда, перец и герань.\nБазовые ноты: амброксан, пачули и ветивер.\n\nZenith Blue транслирует идею сдержанной элегантности, силы и ясности. В нём энергия и свежесть гармонично соседствуют с глубиной и умиротворением. Аромат звучит дорого и современно, хорошо подчёркивает стиль. Он универсален: свежесть располагает к тёплому времени года, а древесно-амбровая база позволяет носить его и в прохладную погоду. Подходит для разных ситуаций — от деловой встречи до вечера с друзьями.\n\nСтойкость хорошая: на коже аромат держится 6–8 часов, на одежде может сохраняться до суток.\nШлейф выраженный: в первые пару часов он хорошо ощущается на расстоянии вытянутой руки, потом становится ближе к коже.\n\nВ раскрытии есть нюанс: перец в сердце не всегда звучит очень ярко — некоторые сначала его почти не слышат, а в фокусе оказываются бергамот, лаванда и амброксан.\n\nДюп — это доступный аналог популярного парфюма: он передаёт характер и основные ноты оригинала, но стоит дешевле и выпускается под другим названием. Это не подделка, а легальная интерпретация — чтобы попробовать трендовый аромат без больших трат или носить его каждый день, не расходуя дорогой оригинал",
