    "description": "Тёплый, обволакивающий унисекс-аромат, где главная героиня — ваниль, но звучит она не просто сладко, а многогранно: с гурманскими, цветочными и смолисто-древесными акцентами.\n\nВерхние ноты: бергамот, ром, засахаренный апельсин.\nНоты сердца: жасмин, фиалка, стиракс.\nБазовые ноты: пачули, ваниль, бензоин.\n\nZenith Vanilla — это ода роскошной, зрелой ванили в восточно-цветочном ключе. Он создаёт атмосферу тепла, уюта и лёгкой загадочности. Многие находят в нём интересные «коктейльные» оттенки — что-то среднее между ванильной колой и пряным глинтвейном. Аромат универсален: его можно носить и днём, но особенно красиво он раскрывается вечером и на свиданиях.\n\nСтойкость хорошая: на коже аромат держится 6–8 часов, на одежде может сохраняться до суток.\nШлейф выраженный, плотный.\nСезонность: лучше всего раскрывается в прохладную погоду — осенью, зимой, ранней весной. В сильную жару он может показаться слишком тяжёлым.\n\nДюп — это доступный аналог популярного парфюма: он передаёт характер и основные ноты оригинала, но стоит дешевле и выпускается под другим названием. Это не подделка, а легальная интерпретация — чтобы попробовать трендовый аромат без больших трат или носить его каждый день, не расходуя дорогой оригинал",
