    "description": "Концепция аромата — передать атмосферу современного Лондона, где гармонично сплетаются классика и современность. Он адресован элегантному, уверенному в себе мужчине, который ценит стиль, но при этом остаётся верным традициям. Многие описывают его как благородный, сдержанный, уютный и очень атмосферный. Часто возникают ассоциации с мягким кашемировым шарфом, чашкой горячего чая у камина или прогулкой по дождливым городским улицам.\n\nАромат особенно хорошо раскрывается в прохладную погоду — осенью или зимой. Его можно носить и в повседневной жизни, и для особых случаев: свиданий, вечерних выходов.\n\nВерхние ноты: корица, лаванда, бергамот.\nНоты сердца: кожа, мимоза.\nБазовые ноты: гваяковое дерево, лист табака, опопонакс, дубовый мох.\n\nКонцентрация — туалетная вода\nСтойкость — средняя (примерно 2–5 часов)\nШлейф — средний",
