    "prices": {
      "3ml": 660,
      "5ml": 1000,
      "10ml": 1800,
      "15ml": 2400,
      "20ml": 2800
    },
    "description": "Afnan 9 PM Night Out — яркий вечерний унисекс‑аромат из восточной пряной группы. Его можно описать как «энергию ночной вечеринки»: дерзкую, сладкую, но с благородной глубиной.\nПо настроению он ближе к вечерним, клубным или праздничным образам: в нём есть драйв и лёгкая театральность.\n\nВерхние ноты: питахайя, лаванда, коньяк, яблоко, бергамот. Старт яркий и неожиданный: терпкий коньяк встречается с прохладной лавандой и свежестью бергамота, а экзотическая питахайя и сочное яблоко добавляют фруктовую игривость.\nНоты сердца: тоффи, замша, кардамон, кедр, Mahonial. Сердце становится теплее и «гурманское»: сливочная нота тоффи обволакивает, замша добавляет тактильной мягкости, кардамон — пряной терпкости, а кедр — древесной структуры.\nБазовые ноты: бобы тонка, Ambrofix, Akigalawood, пачули. База глубокая и манящая: сладкие бобы тонка сплетаются с дымным Akigalawood (древесная молекула с лёгким «удовым» характером), тёплым Ambrofix и тёмным пачули",
    "url": "http://volodiumparfum.ru/catalog/tproduct/383373203613-afnan-9-pm-night-out"
