    "description": "Khaliji Amber XXI Pure Amber — унисекс-парфюмерная вода в восточно-древесном ключе. Вдохновлена Clive Christian Blonde Amber. В старте — кашемировое и ванильное дерево с ликёрной нотой, в сердце — кедр, амбра и тростниковый сахар, а шлейф из мускуса, бобов тонка, лабданума и сандала оставляет кремово-янтарный след. Идеален для особых случаев и прохладной погоды\n\nВерхние ноты: восточный аккорд, кашемировое дерево, ванильное дерево, лёгкая ликёрная нота — создают тёплый, обволакивающий старт с намёком на сладкую глубину.\nНоты сердца: кедр, амбра, тростниковый сахар — дают смолистую древесность, тёплую янтарную сладость и мягкую карамельность.\nБазовые ноты: мускус, бобы тонка, лабданум, сандаловое дерево — формируют долгий кремово‑янтарный шлейф с бальзамической теплотой и лёгкой пряностью.",
