    "description": "Trussardi The Courtyards of Castello Sforzesco — унисекс-парфюмерная вода, выпущенная итальянским брендом Trussardi в 2022 году. Аромат вдохновлён величественным замком Сфорцеско в Милане, где переплетаются история, роскошь и тайна.\n\nЭтот древесно-пряный парфюм создан для тех, кто ценит нишевую парфюмерию с готическим шармом и роскошным звучанием. Композиция переносит дух средневекового замка в современные духи, окутывая носителя аурой уверенности и изысканности.\n\nВерхние ноты: бергамот, шафран и олибанум. Эти ноты создают ощущение входа в парадный двор под башней Филарета, наполняя аромат свежестью и пряностью.\nНоты сердца: марокканская роза, мёд, герань, белая роза и розовый перец. Этот дуэт роз в сочетании с пряными акцентами и сладостью мёда придаёт композиции мягкую глубину и цветочную нежность.\nБазовые ноты: лабданум, бензоин и clearwood. Они обеспечивают стойкий шлейф с тёплыми древесными и смолистыми оттенками, оставляя мистическое послевкусие.",
