    "prices": {
      "3ml": 930,
      "5ml": 1500,
      "10ml": 2700,
      "15ml": 3800,
      "20ml": 4600
    },
    "description": "Верхние ноты: звёздчатый анис, кардамон (из Гватемалы), итальянский лимон. Старт получается ярким: пряность аниса и кардамона сочетается со свежей, чуть горьковатой цитрусовостью лимона.\nНоты сердца: календула, пачули, чёрный перец, элеми. Здесь раскрывается сложность: нежная, чуть «лекарственная» нота календулы переплетается с древесно-смолистыми оттенками пачулей, пикантностью чёрного перца и бальзамической, чуть смолистой нотой элеми.\nБазовые ноты: ликёр, мадагаскарская ваниль. В шлейфе тёплая, обволакивающая ваниль сочетается с лёгкой, не приторной алкогольностью ликёра.\n\nКакое впечатление оставляет? Многие описывают его как тёплый, уютный, сложный и многогранный. В раскрытии можно уловить разные грани: от травянисто-аптечной (из-за календулы) до пряно-смолистой и в финале — сладковато-ванильной с лёгким алкогольным оттенком. Часто возникают ассоциации с травяным чаем, настойкой, глинтвейном или даже со старинной аптекарской лавкой с эликсирами. Аромат звучит по-разному на разной коже: кто-то ярче слышит травы и анис, а кто-то — более выраженную ваниль и ликёр",
    "url": "http://volodiumparfum.ru/catalog/tproduct/562656583073-trussardi-i-vicoli-via-fiori-chiari"
