    "description": "Аромат вдохновлён мистической красотой храмового комплекса Ангкор-Ват в Камбодже и атмосферой камбоджийских джунглей. Он призван перенести обладателя в это таинственное место, где вековые деревья сплетаются с каменными стенами святилищ.\n\nВерхние ноты: бергамот и груша. Старт получается свежим, с искристой цитрусовой нотой бергамота и сочной фруктовой сладостью груши.\nНоты сердца: жасмин и бурбонский перец. Здесь к цветочной нежности жасмина добавляется лёгкая пряная острота перца — это придаёт композиции глубину и интригу.\nБазовые ноты: пачули, белый мускус и гваяковое дерево. В базе раскрывается главная тема: пачули звучат элегантно и бархатисто, без тяжеловесной землистости. Гваяк добавляет благородную теплоту и древесную глубину, а белый мускус окутывает кожу невесомой, пудровой дымкой.",
