    "description": "Верхние ноты: шафран, мускатный орех, кардамон, корица. Сразу после нанесения даёт яркий, согревающий всплеск специй.\nНоты сердца: роза, уд, гвоздика (пряность). Здесь специи постепенно смягчаются: роза добавляет чувственности, уд — дымных, древесно-бальзамических оттенков, а гвоздика вносит пряную грань.\nБазовые ноты: мускус, пачули, сандал. В финале остаётся тёплый, обволакивающий шлейф: сандал даёт сливочную древесность, пачули — чуть землистую, травянистую глубину, а мускус смягчает композицию и продлевает её звучание\n\nSun Drop тёплый, уютный, слегка мистический аромат. Он ассоциируется с солнечным светом, но не с резким полуденным зноем, а с тёплыми, «золотистыми» лучами — например, на закате или в прохладный осенний день. В раскрытии чувствуется баланс: специи не доминируют грубо, а гармонично переплетаются с цветочной нотой и древесиной.",
