    "description": "Верхние ноты: лимон, бергамот, мята, озоновый аккорд.\nСтарт очень бодрый и резкий: цитрусы дают искру, мята — мгновенную прохладу, а озоновый оттенок имитирует ощущение свежего воздуха после грозы или у водопада.\nНоты сердца: лаванда, зелёные листья, водные ноты, можжевельник.\nВ сердце аромат становится «травянисто‑минеральным»: лаванда добавляет классическую фужерную чистоту, зелёные и водные ноты поддерживают ощущение свежести, а можжевельник даёт тонкую хвойную грань, которая не даёт композиции стать слишком простой.\nБазовые ноты: белый мускус, кедр, амбра, лёд (акватический/минеральный аккорд).\nБаза не тяжёлая: белый мускус делает звучание мягким, кедр — чуть древесным, амбра добавляет лёгкую тёплую подложку, а минерально‑акватический оттенок сохраняет ту самую «ледяную» прохладу даже в финале.",
