    "prices": {
      "3ml": 510,
      "5ml": 800,
      "10ml": 1500,
      "15ml": 2100,
      "20ml": 2600
    },
    "description": "Верхние ноты: гуава, ананас, яблоко, апельсин.\nСтарт очень сочный и свежий: сразу чувствуется фруктовая волна, будто только что нарезали тропические плоды. Ананас и гуава задают главный «коктейльный» тон, цитрусы добавляют искристости, а яблоко — лёгкую хрустящую грань.\nНоты сердца: кокос, жасмин самбак, ландыш.\nНа этом этапе сладость становится мягче: кокос даёт кремовую, «пляжную» текстуру, а цветы (жасмин и ландыш) добавляют воздушности и чистоты — чтобы композиция не звучала как сироп.\nБазовые ноты: ваниль, амбра, мускус, сандал.\nБаза тёплая и обволакивающая: ваниль отвечает за мягкую сладость, амбра и мускус делают шлейф чувственным и стойким, а сандал добавляет древесную сливочность, чтобы аромат не был слишком «сахарным».\n\nСначала это максимально яркий фруктовый всплеск — почти как свежеприготовленный смузи или газировка с тропическими фруктами. Через 10–20 минут кокос и цветы сглаживают резкость, и аромат становится кремово‑цветочным, но всё ещё очень свежим. В базе остаётся тёплый сладковатый шлейф с намёком на древесину.",
    "url": "http://volodiumparfum.ru/catalog/tproduct/912591935813-french-avenue-guava-colada"
