    "category": "perfume",
    "notesFamily": "woody",
    "image": "https://static.tildacdn.com/stor6331-6239-4063-a131-353331323961/f35d445d2e5939afa9b7e3a3d84eec8a.png",
    "badge": "Бестселлер",
