    "description": "Аромат вдохновлён многогранностью Стамбула: пёстрыми базарами со специями, роскошью османских дворцов, атмосферой хаммамов и морским бризом. Создатели хотели передать ощущение путешествия по городу, где смешиваются разные культуры, запахи и эмоции. Дизайн коллекции тоже отсылает к восточной эстетике — сочетает роскошь султанских покоев с современной элегантностью\n\nВерхние ноты: бергамот, корица, гвоздика (пряность), шафран. Старт получается искрящимся, пряно-цитрусовым, с лёгкой пикантностью. Шафран добавляет чуть йодистой, специфической грани.\nНоты сердца: чёрная орхидея, жасмин, фиалка. Здесь композиция смягчается: цветочный блок придаёт бархатистость, утончённость и восточную элегантность. Иногда в описаниях также упоминают франжипани.\nБазовые ноты: сандал, амбра, кедр, ваниль, пачули, мускус, уд. База формирует густой, смолисто-древесный шлейф. Уд добавляет дымную, восточную томность, а ваниль и пачули — объём и тёплую сладость",
