    "description": "Аромат вдохновлен тем самым «золотым часом» — волшебное мгновение, когда солнце низко над горизонтом и заливает город тёплым, медовым светом. Парфюмер хотел передать тёплую, сияющую атмосферу Стамбула: свежесть раннего утра (когда будто распускаются жасмин и нероли) плавно перетекает в обволакивающее, бархатистое тепло вечера (с нотами карамелизированного кокоса, ванили и сухой амбры, которая добавляет лёгкий контрастный акцент, словно удлинённая тень). Автор ольфакторной формулы — французский парфюмер Паскаль Горен\n\nВерхние ноты: груша и нероли. Дают сочный, свежий старт.\nНоты сердца: жасмин и карамелизированный кокос. Здесь фруктовая свежесть смягчается, появляется кремовая, чуть сладковатая грань.\nБазовые ноты: сухая амбра, лабданум и ваниль. Формируют тёплый, обволакивающий шлейф с мягкими сливочными и смолистыми оттенками.\n\nАромат звучит очень уютно, тепло и сбалансированно: в нём есть и свежесть, и сладость, и восточная глубина.",
